import "core-js/modules/es.array.push.js";
import "core-js/modules/es.iterator.constructor.js";
import "core-js/modules/es.iterator.filter.js";
import "core-js/modules/es.iterator.find.js";
import request from '@/utils/request';
import config from '@/config/config';
export default {
  name: 'RouteDetail',
  data() {
    return {
      routeDetail: null,
      loading: false,
      loadError: false,
      activeDay: '1'
    };
  },
  computed: {
    // 当前选中的天的行程项
    currentDayItems() {
      if (!this.routeDetail || !this.routeDetail.itinerary) return [];
      const day = this.routeDetail.itinerary.find(d => d.dayNum.toString() === this.activeDay);
      return day ? day.items : [];
    }
  },
  mounted() {
    this.loadRouteDetail();
  },
  methods: {
    // 获取类型样式类
    getTypeClass(type) {
      const classMap = {
        'attraction': 'attraction',
        'food': 'food',
        'hotel': 'hotel',
        'route': 'route'
      };
      return classMap[type] || '';
    },
    // 获取类型图标
    getTypeIcon(type) {
      const iconMap = {
        'attraction': 'el-icon-location-outline',
        'food': 'el-icon-food',
        'hotel': 'el-icon-office-building',
        'route': 'el-icon-direction'
      };
      return iconMap[type] || 'el-icon-more';
    },
    // 切换描述展开/收起
    toggleDescription(item) {
      this.$set(item, 'showFull', !item.showFull);
    },
    // 加载路线详情
    async loadRouteDetail() {
      const recommendationId = this.$route.params.id;
      if (!recommendationId) {
        this.$message.error('缺少路线ID');
        this.goBack();
        return;
      }
      this.loading = true;
      this.loadError = false;
      try {
        const res = await request({
          url: config.backHost + `/api/routeRecommendation/detail/${recommendationId}`,
          method: 'POST'
        });
        if (res.code === 200 && res.data) {
          this.routeDetail = res.data;
          this.activeDay = '1';
        } else {
          this.$message.error(res.msg || '加载失败');
          this.loadError = true;
        }
      } catch (error) {
        console.error('加载路线详情失败:', error);
        this.$message.error('加载路线详情失败');
        this.loadError = true;
      } finally {
        this.loading = false;
      }
    },
    // 返回
    goBack() {
      this.$router.go(-1);
    },
    // 删除路线
    deleteRoute() {
      const recommendationId = this.$route.params.id;
      this.$confirm('确定要删除这条行程记录吗？', '提示', {
        confirmButtonText: '确定',
        cancelButtonText: '取消',
        type: 'warning'
      }).then(async () => {
        try {
          const res = await request({
            url: config.backHost + `/api/routeRecommendation/delete/${recommendationId}`,
            method: 'POST'
          });
          if (res.code === 200) {
            this.$message.success('删除成功');
            this.goBack();
          } else {
            this.$message.error(res.msg || '删除失败');
          }
        } catch (error) {
          console.error('删除失败:', error);
          this.$message.error('删除失败');
        }
      }).catch(() => {
        this.$message.info('已取消删除');
      });
    },
    // 获取图片数组
    getImages(imagesStr) {
      if (!imagesStr) return [];
      try {
        return JSON.parse(imagesStr);
      } catch (e) {
        return imagesStr.split(',').filter(img => img);
      }
    },
    // 获取交通方式文本
    getTransportText(type) {
      const map = {
        'drive': '自驾',
        'bus': '公交',
        'taxi': '打车',
        'walking': '步行',
        'walk': '步行'
      };
      return map[type] || type;
    },
    // 格式化时长
    formatDuration(minutes) {
      if (!minutes && minutes !== 0) return '暂无数据';
      const hours = Math.floor(minutes / 60);
      const mins = minutes % 60;
      if (hours > 0 && mins > 0) {
        return `${hours}小时${mins}分钟`;
      } else if (hours > 0) {
        return `${hours}小时`;
      } else {
        return `${mins}分钟`;
      }
    },
    // 获取费用样式类
    getCostClass(summary) {
      if (summary.estimatedCost <= summary.budget) {
        return 'cost under-budget';
      } else {
        return 'cost over-budget';
      }
    },
    // 跳转到景点详情
    goToAttractionDetail(attractionId) {
      console.log('景点 ID:', attractionId);
      if (attractionId) {
        this.$router.push({
          name: 'attractionDetail',
          query: {
            id: attractionId
          }
        });
      } else {
        this.$message.warning('景点信息不完整');
      }
    },
    // 跳转到酒店详情
    goToHotelDetail(hotelId) {
      console.log('酒店 ID:', hotelId);
      if (hotelId) {
        this.$router.push({
          name: 'hotelInfoDetail',
          query: {
            id: hotelId
          }
        });
      } else {
        this.$message.warning('酒店信息不完整');
      }
    },
    // 跳转到美食详情
    goToFoodDetail(foodId) {
      console.log('美食 ID:', foodId);
      console.log('完整美食对象:', arguments[0] === undefined ? '请查看调用处' : '检查 item 对象');
      if (foodId) {
        this.$router.push({
          name: 'foodDetail',
          query: {
            id: foodId
          }
        });
      } else {
        this.$message.warning('美食信息不完整，请联系后端确认返回数据中是否包含 foodId 或 id 字段');
      }
    },
    // 打开地图导航
    async openNavigation(item) {
      console.log('导航数据:', item);

      // 优先使用经纬度坐标
      if (item.fromLongitude && item.fromLatitude && item.toLongitude && item.toLatitude) {
        const fromCoord = `${item.fromLongitude},${item.fromLatitude}`;
        const toCoord = `${item.toLongitude},${item.toLatitude}`;
        let mode = 'drive';
        if (item.transportType === 'bus') {
          mode = 'bus';
        } else if (item.transportType === 'walk' || item.transportType === 'walking') {
          mode = 'walk';
        }
        const amapUrl = `https://uri.amap.com/navigation?from=${fromCoord}&to=${toCoord}&mode=${mode}&src=贵阳旅游攻略系统`;
        window.open(amapUrl, '_blank');
      } else if (item.fromLocation && item.toLocation) {
        try {
          this.$message.info('正在获取位置信息...');
          const [fromRes, toRes] = await Promise.all([request({
            url: config.backHost + '/api/common/geoCode',
            method: 'POST',
            data: {
              address: item.fromLocation
            }
          }), request({
            url: config.backHost + '/api/common/geoCode',
            method: 'POST',
            data: {
              address: item.toLocation
            }
          })]);
          if (fromRes.code === 200 && fromRes.data && toRes.code === 200 && toRes.data) {
            const fromCoord = `${fromRes.data.longitude},${fromRes.data.latitude}`;
            const toCoord = `${toRes.data.longitude},${toRes.data.latitude}`;
            let mode = 'drive';
            if (item.transportType === 'bus') {
              mode = 'bus';
            } else if (item.transportType === 'walk' || item.transportType === 'walking') {
              mode = 'walk';
            }
            const amapUrl = `https://uri.amap.com/navigation?from=${fromCoord}&to=${toCoord}&mode=${mode}&src=贵阳旅游攻略系统`;
            window.open(amapUrl, '_blank');
          } else {
            this.$message.warning('无法获取精确坐标，将使用地址名称导航');
            const amapUrl = `https://uri.amap.com/navigation?from=${encodeURIComponent(item.fromLocation)}&to=${encodeURIComponent(item.toLocation)}`;
            window.open(amapUrl, '_blank');
          }
        } catch (error) {
          console.error('获取坐标失败:', error);
          this.$message.error('获取位置信息失败，请稍后重试');
        }
      } else {
        this.$message.warning('路线信息不完整，无法导航');
      }
    }
  }
};
